import React from "react"
import { useState, useEffect } from "react";
import "./"


function Taskflow() {

    const [Search, setSearch] = useState("");
    return (
        <div>
            <header className="header">
                <h1>TaskFlow</h1>
            </header>

            <div className="card">
                <h2>List View — "/"</h2>
                <input
                    type="text"
                    placeholder="Search tasks..."
                    value={Search}
                    onChange={(e) => setSearch(e.target.value)}
                />
            </div>
        </div>
    );
}

export default Taskflow
